#!/bin/bash
# Runs TLC on the configurations of SemiSyncFailover.tla and checks each outcome against the
# expected one: "pass" (no error) or the invariant that must be violated.
#
# Usage: ./run.sh [config ...]      (default: every configuration below, in order)
#
# TLA2TOOLS_JAR  path of tla2tools.jar (default: tla2tools.jar next to this script; never commit it)
# TLC_HEAP       Java heap (default 8g)
# TLC_WORKERS    TLC worker threads (default 4)
# The TLC outputs go to out/<config>.out; ./trace.py out/<config>.out prints a counterexample
# compactly. The configurations are generated by mkcfg.sh (its first line names the command).
set -u
cd "$(dirname "$0")"
if [ ! -f "${TLA2TOOLS_JAR:-tla2tools.jar}" ]; then
  echo "tla2tools.jar not found: set TLA2TOOLS_JAR (https://github.com/tlaplus/tlaplus/releases)" >&2
  exit 2
fi

# config:expected outcome. Each bug configuration is the code on main with the fixes of the
# configurations above it, so that TLC reports that bug and not an earlier one.
EXPECTED=(
  b1_srs_ack:NoUnbackedAck
  n1_retrying_io:NoLostAck
  s11_relay_recovery:NoLostAck
  stale_fix_replica:NoLostAck
  ers_stale_record:NoErrantServingReplica
  b5_stale_repoint:NoLostAck
  detached_repoint:NoLostAck
  b7_abort_leaves_repoint:NoErrantServingReplica
  s12_startup_repoint:NoLostAck
  current_fixed:pass
  s12_fixed:pass
  orcs2_lease_expiry:NoLostAck
  orcs2_no_expiry:pass
)

expected_of() {
  for e in "${EXPECTED[@]}"; do
    [ "${e%%:*}" = "$1" ] && { echo "${e#*:}"; return; }
  done
}

configs=("$@")
if [ ${#configs[@]} -eq 0 ]; then
  for e in "${EXPECTED[@]}"; do configs+=("${e%%:*}"); done
fi

rc=0
for c in "${configs[@]}"; do
  want=$(expected_of "$c")
  start=$(date +%s)
  ./run1.sh "$c" > /dev/null
  out=out/$c.out
  if grep -q "No error has been found" "$out"; then
    got=pass
  elif v=$(grep -oE "Invariant [A-Za-z]+ is violated" "$out"); then
    got=$(echo "$v" | awk '{print $2}')
  else
    got="error (see $out)"
  fi
  states=$(grep -oE "[0-9,]+ distinct states found" "$out" | tail -1)
  status=OK
  [ "$got" = "$want" ] || { status=UNEXPECTED; rc=1; }
  printf '%-26s expected %-24s got %-24s %-10s %5ss  %s\n' "$c" "$want" "$got" "$status" $(( $(date +%s) - start )) "$states"
done
exit $rc
